  static void box(Model m, String comp, String tag, int dim, double x0, double y0, double x1, double y1, boolean is3d, String label) {
    m.component(comp).selection().create(tag, "Box");
    m.component(comp).selection(tag).set("entitydim", dim);
    m.component(comp).selection(tag).set("xmin", x0);
    m.component(comp).selection(tag).set("xmax", x1);
    m.component(comp).selection(tag).set("ymin", y0);
    m.component(comp).selection(tag).set("ymax", y1);
    if (is3d) {
      m.component(comp).selection(tag).set("zmin", -0.5);
      m.component(comp).selection(tag).set("zmax", 40.5);
    }
    m.component(comp).selection(tag).set("condition", "inside");
    if (label != null) m.component(comp).selection(tag).label(label);
  }
  static void union(Model m, String comp, String tag, int dim, String[] in, String label) {
    m.component(comp).selection().create(tag, "Union");
    m.component(comp).selection(tag).set("entitydim", dim);
    m.component(comp).selection(tag).set("input", in);
    m.component(comp).selection(tag).label(label);
  }
